import os
import sqlite3
from datetime import datetime, timezone


def get_db_path() -> str:
    return os.getenv('SHORTENER_DB_PATH', 'url_shortener.db')


def _connect() -> sqlite3.Connection:
    return sqlite3.connect(get_db_path(), timeout=30.0)


def init_db() -> None:
    conn = _connect()
    try:
        with conn:
            conn.execute(
                'CREATE TABLE IF NOT EXISTS urls ('
                'code TEXT PRIMARY KEY, '
                'original_url TEXT NOT NULL, '
                'created_at TEXT NOT NULL, '
                'clicks INTEGER NOT NULL DEFAULT 0)'
            )
    finally:
        conn.close()


def code_exists(code: str) -> bool:
    if not code:
        return False
    init_db()
    conn = _connect()
    try:
        row = conn.execute(
            'SELECT 1 FROM urls WHERE code = ? LIMIT 1',
            (code,),
        ).fetchone()
        return row is not None
    finally:
        conn.close()


def save_url(code: str, original_url: str) -> bool:
    if not code or not original_url:
        return False
    init_db()
    conn = _connect()
    try:
        with conn:
            conn.execute(
                'INSERT INTO urls (code, original_url, created_at, clicks) VALUES (?, ?, ?, 0)',
                (code, original_url, datetime.now(timezone.utc).isoformat()),
            )
        return True
    except sqlite3.IntegrityError:
        return False
    finally:
        conn.close()


def get_url_and_increment(code: str) -> str | None:
    if not code:
        return None
    init_db()
    conn = _connect()
    try:
        with conn:
            conn.execute('BEGIN IMMEDIATE')
            row = conn.execute(
                'SELECT original_url FROM urls WHERE code = ?',
                (code,),
            ).fetchone()
            if not row:
                return None
            conn.execute(
                'UPDATE urls SET clicks = clicks + 1 WHERE code = ?',
                (code,),
            )
            return row[0]
    finally:
        conn.close()


def get_url_metadata(code: str) -> dict | None:
    if not code:
        return None
    init_db()
    conn = _connect()
    try:
        row = conn.execute(
            'SELECT code, original_url, created_at, clicks FROM urls WHERE code = ?',
            (code,),
        ).fetchone()
        if not row:
            return None
        return {
            'code': row[0],
            'original_url': row[1],
            'created_at': row[2],
            'clicks': row[3],
        }
    finally:
        conn.close()


def get_stats(code: str) -> dict | None:
    return get_url_metadata(code)

import io
import os
import re
import secrets
import string
import struct
import zlib
from urllib.parse import urlparse
from app.storage import get_stats, get_url_and_increment, get_url_metadata, save_url

ALPHABET = string.ascii_letters + string.digits
ALIAS_MIN_LENGTH = 3
ALIAS_MAX_LENGTH = 20
ALIAS_PATTERN = re.compile(r'^[a-zA-Z0-9_-]+$')
ALLOWED_URL_SCHEMES = frozenset({'http', 'https'})
DEFAULT_BASE_URL = 'http://localhost:8000'
RESERVED_ALIASES = frozenset({
    'health',
    'shorten',
    'stats',
    'qr',
    'metadata',
    'meta',
    'links',
    'info',
    'api',
    'docs',
    'redoc',
    'openapi.json',
    'favicon.ico',
    'robots.txt',
})

_QR_VERSIONS_L = (
    (1, 17, 7, 1, 19, 0, 0, ()),
    (2, 32, 10, 1, 34, 0, 0, (6, 18)),
    (3, 53, 15, 1, 55, 0, 0, (6, 22)),
    (4, 78, 20, 1, 80, 0, 0, (6, 26)),
    (5, 106, 26, 1, 108, 0, 0, (6, 30)),
    (6, 134, 18, 2, 68, 0, 0, (6, 34)),
    (7, 154, 20, 2, 78, 0, 0, (6, 22, 38)),
    (8, 192, 24, 2, 97, 0, 0, (6, 24, 42)),
    (9, 230, 30, 2, 116, 0, 0, (6, 26, 46)),
    (10, 271, 18, 2, 68, 2, 69, (6, 28, 50)),
)


class InvalidInputError(ValueError):
    pass


class AliasConflictError(ValueError):
    pass


def generate_code(length: int = 6) -> str:
    return ''.join(secrets.choice(ALPHABET) for _ in range(length))


def validate_target_url(url: str) -> str:
    if not isinstance(url, str):
        raise InvalidInputError('URL must be a string.')
    cleaned = url.strip()
    if not cleaned:
        raise InvalidInputError('URL must not be empty.')
    if any(ord(ch) < 32 or ord(ch) == 127 for ch in cleaned):
        raise InvalidInputError('URL contains invalid control characters.')
    parsed = urlparse(cleaned)
    if parsed.scheme.lower() not in ALLOWED_URL_SCHEMES:
        raise InvalidInputError('URL scheme must be http or https.')
    if not parsed.netloc or not parsed.hostname:
        raise InvalidInputError('URL must include a valid host.')
    return cleaned


def validate_custom_alias(alias: str) -> str:
    if not isinstance(alias, str):
        raise InvalidInputError('Custom alias must be a string.')
    if not (ALIAS_MIN_LENGTH <= len(alias) <= ALIAS_MAX_LENGTH):
        raise InvalidInputError(
            f'Custom alias must be between {ALIAS_MIN_LENGTH} and {ALIAS_MAX_LENGTH} characters.'
        )
    if not ALIAS_PATTERN.fullmatch(alias):
        raise InvalidInputError(
            'Custom alias may only contain letters, numbers, hyphens, and underscores.'
        )
    if alias.lower() in RESERVED_ALIASES:
        raise InvalidInputError('Custom alias uses a reserved route name.')
    return alias


def get_base_url(fallback_base_url: str | None = None) -> str:
    configured = (os.getenv('SHORTENER_BASE_URL') or os.getenv('BASE_URL') or '').strip()
    if configured:
        return configured.rstrip('/')
    if fallback_base_url and fallback_base_url.strip():
        return fallback_base_url.strip().rstrip('/')
    return DEFAULT_BASE_URL


def format_shareable_url(code: str, base_url: str | None = None) -> str:
    clean_code = code.lstrip('/')
    resolved_base = get_base_url(base_url)
    return f'{resolved_base}/{clean_code}'


def create_short_url(original_url: str, custom_alias: str | None = None) -> str:
    validated_url = validate_target_url(original_url)
    if custom_alias is not None:
        validated_alias = validate_custom_alias(custom_alias)
        if not save_url(validated_alias, validated_url):
            raise AliasConflictError('Custom alias already exists.')
        return validated_alias
    for _ in range(5):
        code = generate_code()
        if code.lower() in RESERVED_ALIASES:
            continue
        if save_url(code, validated_url):
            return code
    raise RuntimeError('Failed to generate unique short code.')


def create_short_link(
    original_url: str,
    custom_alias: str | None = None,
    base_url: str | None = None,
) -> dict:
    validated_url = validate_target_url(original_url)
    code = create_short_url(validated_url, custom_alias)
    return {
        'code': code,
        'short_url': format_shareable_url(code, base_url),
        'original_url': validated_url,
    }


def resolve_short_url(code: str) -> str | None:
    if not code:
        return None
    return get_url_and_increment(code)


def fetch_url_stats(code: str) -> dict | None:
    return get_stats(code)


def get_link_metadata(code: str, base_url: str | None = None) -> dict | None:
    if not code:
        return None
    metadata = get_url_metadata(code)
    if not metadata:
        return None
    return {
        'code': metadata['code'],
        'original_url': metadata['original_url'],
        'short_url': format_shareable_url(metadata['code'], base_url),
        'created_at': metadata['created_at'],
        'clicks': metadata['clicks'],
    }


def _gf_mul(a: int, b: int) -> int:
    res = 0
    while b:
        if b & 1:
            res ^= a
        a <<= 1
        if a & 0x100:
            a ^= 0x11D
        b >>= 1
    return res


def _rs_generator(degree: int) -> list[int]:
    poly = [1]
    root = 1
    for _ in range(degree):
        next_poly = [0] * (len(poly) + 1)
        for idx, coeff in enumerate(poly):
            next_poly[idx] ^= coeff
            next_poly[idx + 1] ^= _gf_mul(coeff, root)
        poly = next_poly
        root = _gf_mul(root, 2)
    return poly


def _rs_remainder(data: list[int], ec_count: int) -> list[int]:
    gen = _rs_generator(ec_count)
    rem = list(data) + [0] * ec_count
    for i in range(len(data)):
        factor = rem[i]
        if factor:
            for j in range(1, len(gen)):
                rem[i + j] ^= _gf_mul(gen[j], factor)
    return rem[len(data):]


def _build_qr_matrix(payload: bytes) -> list[list[bool]]:
    spec = next((item for item in _QR_VERSIONS_L if len(payload) <= item[1]), None)
    if spec is None:
        raise InvalidInputError('URL exceeds maximum length for QR code generation.')
    version, _, ec_len, g1_cnt, g1_len, g2_cnt, g2_len, align_coords = spec
    total_data_bytes = g1_cnt * g1_len + g2_cnt * g2_len

    bits: list[int] = []
    for val, width in ((0b0100, 4), (len(payload), 8)):
        for shift in range(width - 1, -1, -1):
            bits.append((val >> shift) & 1)
    for byte in payload:
        for shift in range(7, -1, -1):
            bits.append((byte >> shift) & 1)
    bits.extend([0] * min(4, total_data_bytes * 8 - len(bits)))
    while len(bits) % 8:
        bits.append(0)

    data_bytes = [
        sum(bits[i + b] << (7 - b) for b in range(8)) for i in range(0, len(bits), 8)
    ]
    pad_cycle = (0xEC, 0x11)
    pad_idx = 0
    while len(data_bytes) < total_data_bytes:
        data_bytes.append(pad_cycle[pad_idx % 2])
        pad_idx += 1

    data_blocks: list[list[int]] = []
    ec_blocks: list[list[int]] = []
    offset = 0
    for count, block_len in ((g1_cnt, g1_len), (g2_cnt, g2_len)):
        for _ in range(count):
            block = data_bytes[offset:offset + block_len]
            offset += block_len
            data_blocks.append(block)
            ec_blocks.append(_rs_remainder(block, ec_len))

    codewords: list[int] = []
    max_data = max(len(b) for b in data_blocks)
    for i in range(max_data):
        for block in data_blocks:
            if i < len(block):
                codewords.append(block[i])
    for i in range(ec_len):
        for block in ec_blocks:
            codewords.append(block[i])

    stream = [(cw >> s) & 1 for cw in codewords for s in range(7, -1, -1)]

    size = 17 + 4 * version
    grid: list[list[bool]] = [[False] * size for _ in range(size)]
    fixed: list[list[bool]] = [[False] * size for _ in range(size)]

    def set_fixed(r: int, c: int, val: bool) -> None:
        if 0 <= r < size and 0 <= c < size:
            grid[r][c] = val
            fixed[r][c] = True

    for top, left in ((0, 0), (0, size - 7), (size - 7, 0)):
        for dr in range(-1, 8):
            for dc in range(-1, 8):
                is_dark = (
                    0 <= dr <= 6
                    and 0 <= dc <= 6
                    and (
                        dr in (0, 6)
                        or dc in (0, 6)
                        or (2 <= dr <= 4 and 2 <= dc <= 4)
                    )
                )
                set_fixed(top + dr, left + dc, is_dark)

    for r in align_coords:
        for c in align_coords:
            if fixed[r][c]:
                continue
            for dr in range(-2, 3):
                for dc in range(-2, 3):
                    set_fixed(r + dr, c + dc, max(abs(dr), abs(dc)) != 1)

    for i in range(8, size - 8):
        set_fixed(6, i, i % 2 == 0)
        set_fixed(i, 6, i % 2 == 0)
    set_fixed(size - 8, 8, True)

    for i in range(9):
        if i != 6:
            fixed[8][i] = True
            fixed[i][8] = True
    for i in range(8):
        fixed[8][size - 1 - i] = True
        if i < 7:
            fixed[size - 1 - i][8] = True

    if version >= 7:
        ver_val = version << 12
        for i in range(5, -1, -1):
            if ver_val & (1 << (i + 12)):
                ver_val ^= 0x1F25 << i
        ver_bits = (version << 12) | ver_val
        for i in range(18):
            bit = bool((ver_bits >> i) & 1)
            set_fixed(i // 3, size - 11 + (i % 3), bit)
            set_fixed(size - 11 + (i % 3), i // 3, bit)

    bit_idx = 0
    col = size - 1
    going_up = True
    while col > 0:
        if col == 6:
            col -= 1
        rows = range(size - 1, -1, -1) if going_up else range(size)
        for r in rows:
            for c in (col, col - 1):
                if not fixed[r][c]:
                    raw_bit = bool(stream[bit_idx]) if bit_idx < len(stream) else False
                    mask_bit = ((r + c) % 2) == 0
                    grid[r][c] = raw_bit ^ mask_bit
                    bit_idx += 1
        going_up = not going_up
        col -= 2

    fmt_data = 0b01000
    fmt_val = fmt_data << 10
    for i in range(4, -1, -1):
        if fmt_val & (1 << (i + 10)):
            fmt_val ^= 0x537 << i
    fmt_bits = ((fmt_data << 10) | fmt_val) ^ 0x5412

    top_left_coords = (
        (8, 0), (8, 1), (8, 2), (8, 3), (8, 4), (8, 5), (8, 7), (8, 8),
        (7, 8), (5, 8), (4, 8), (3, 8), (2, 8), (1, 8), (0, 8),
    )
    for idx, (r, c) in enumerate(top_left_coords):
        grid[r][c] = bool((fmt_bits >> (14 - idx)) & 1)
    for idx in range(7):
        grid[size - 1 - idx][8] = bool((fmt_bits >> (14 - idx)) & 1)
    for idx in range(8):
        grid[8][size - 8 + idx] = bool((fmt_bits >> (7 - idx)) & 1)

    return grid


def _png_chunk(chunk_type: bytes, data: bytes) -> bytes:
    crc = zlib.crc32(chunk_type + data) & 0xFFFFFFFF
    return struct.pack('>I', len(data)) + chunk_type + data + struct.pack('>I', crc)


def _render_qr_fallback(data: str, image_format: str) -> bytes:
    matrix = _build_qr_matrix(data.encode('utf-8'))
    size = len(matrix)
    border = 2
    scale = 5
    total = size + border * 2

    if image_format == 'svg':
        paths = [
            f'M{c + border},{r + border}h1v1h-1z'
            for r, row in enumerate(matrix)
            for c, dark in enumerate(row)
            if dark
        ]
        px = total * scale
        svg = (
            f'<svg xmlns="http://www.w3.org/2000/svg" '
            f'viewBox="0 0 {total} {total}" width="{px}" height="{px}" '
            f'shape-rendering="crispEdges">'
            f'<rect width="100%" height="100%" fill="#ffffff"/>'
            f'<path fill="#000000" d="{"".join(paths)}"/>'
            f'</svg>'
        )
        return svg.encode('utf-8')

    dim = total * scale
    white_row = b'\xff' * dim
    raw_rows: list[bytes] = []
    for _ in range(border * scale):
        raw_rows.append(b'\x00' + white_row)
    for row in matrix:
        pixel_row = bytearray([255] * (border * scale))
        for dark in row:
            pixel_row.extend([0 if dark else 255] * scale)
        pixel_row.extend([255] * (border * scale))
        scanline = b'\x00' + bytes(pixel_row)
        for _ in range(scale):
            raw_rows.append(scanline)
    for _ in range(border * scale):
        raw_rows.append(b'\x00' + white_row)

    ihdr = struct.pack('>IIBBBBB', dim, dim, 8, 0, 0, 0, 0)
    idat = zlib.compress(b''.join(raw_rows), level=6)
    return (
        b'\x89PNG\r\n\x1a\n'
        + _png_chunk(b'IHDR', ihdr)
        + _png_chunk(b'IDAT', idat)
        + _png_chunk(b'IEND', b'')
    )


def render_qr_bytes(data: str, image_format: str = 'png') -> bytes:
    fmt = image_format.lower().strip()
    if fmt not in {'png', 'svg'}:
        raise InvalidInputError("Unsupported QR code format. Use 'png' or 'svg'.")
    buf = io.BytesIO()
    try:
        import segno
        qr = segno.make(data, error='m')
        if fmt == 'svg':
            qr.save(buf, kind='svg', xmldecl=False, scale=5)
        else:
            qr.save(buf, kind='png', scale=5, border=2)
        return buf.getvalue()
    except ImportError:
        try:
            import qrcode
            if fmt == 'svg':
                import qrcode.image.svg
                img = qrcode.make(data, image_factory=qrcode.image.svg.SvgPathImage)
                img.save(buf)
            else:
                img = qrcode.make(data)
                img.save(buf, format='PNG')
            return buf.getvalue()
        except ImportError:
            return _render_qr_fallback(data, fmt)


def generate_qr_code(
    code: str,
    base_url: str | None = None,
    image_format: str = 'png',
) -> tuple[bytes, str] | None:
    fmt = image_format.lower().strip()
    if fmt not in {'png', 'svg'}:
        raise InvalidInputError("Unsupported QR code format. Use 'png' or 'svg'.")
    metadata = get_link_metadata(code, base_url=base_url)
    if not metadata:
        return None
    qr_bytes = render_qr_bytes(metadata['short_url'], image_format=fmt)
    media_type = 'image/svg+xml' if fmt == 'svg' else 'image/png'
    return qr_bytes, media_type

from contextlib import asynccontextmanager
import struct
import zlib
from fastapi import FastAPI, HTTPException, Request, Response
from fastapi.responses import RedirectResponse
from pydantic import BaseModel
from app.service import (
    AliasConflictError,
    InvalidInputError,
    create_short_link,
