from app.storage import init_db

_GF_EXP = [0] * 512
_GF_LOG = [0] * 256
_gf_x = 1
for _gf_i in range(255):
    _GF_EXP[_gf_i] = _gf_x
    _GF_LOG[_gf_x] = _gf_i
    _gf_x <<= 1
    if _gf_x & 0x100:
        _gf_x ^= 0x11D
for _gf_i in range(255, 512):
    _GF_EXP[_gf_i] = _GF_EXP[_gf_i - 255]

_QR_L_SPECS = [
    (1, 17, 7, ((1, 19),), 0, []),
    (2, 32, 10, ((1, 34),), 7, [6, 18]),
    (3, 53, 15, ((1, 55),), 7, [6, 22]),
    (4, 78, 20, ((1, 80),), 7, [6, 26]),
    (5, 106, 26, ((1, 108),), 7, [6, 30]),
    (6, 134, 18, ((2, 68),), 7, [6, 34]),
    (7, 154, 20, ((2, 78),), 0, [6, 22, 38]),
    (8, 192, 24, ((2, 97),), 0, [6, 24, 42]),
    (9, 230, 30, ((2, 116),), 0, [6, 26, 46]),
    (10, 271, 18, ((2, 68), (2, 69)), 0, [6, 28, 50]),
]


def _gf_mul(a: int, b: int) -> int:
    if a == 0 or b == 0:
        return 0
    return _GF_EXP[_GF_LOG[a] + _GF_LOG[b]]


def _rs_remainder(data: list[int], ec_count: int) -> list[int]:
    gen = [1]
    for i in range(ec_count):
        nxt = [0] * (len(gen) + 1)
        for j, coef in enumerate(gen):
            nxt[j] ^= coef
            nxt[j + 1] ^= _gf_mul(coef, _GF_EXP[i])
        gen = nxt
    rem = list(data) + [0] * ec_count
    for i in range(len(data)):
        factor = rem[i]
        if factor != 0:
            for j in range(1, len(gen)):
                rem[i + j] ^= _gf_mul(gen[j], factor)
    return rem[len(data):]


def _encode_qr_matrix(text: str) -> list[list[bool]]:
    payload = text.encode('utf-8')
    spec = None
    for candidate in _QR_L_SPECS:
        if len(payload) <= candidate[1]:
            spec = candidate
            break
    if spec is None:
        raise InvalidInputError('URL is too long for QR code generation.')

    version, _, ec_per_block, block_groups, rem_bits, align_pos = spec
    total_data_cw = sum(cnt * dlen for cnt, dlen in block_groups)
    total_data_bits = total_data_cw * 8

    bits: list[int] = [0, 1, 0, 0]
    cc_bits = 8 if version <= 9 else 16
    for shift in range(cc_bits - 1, -1, -1):
        bits.append((len(payload) >> shift) & 1)
    for byte in payload:
        for shift in range(7, -1, -1):
            bits.append((byte >> shift) & 1)
    term = min(4, total_data_bits - len(bits))
    bits.extend([0] * term)
    while len(bits) % 8 != 0:
        bits.append(0)
    pad_toggle = 0
    while len(bits) < total_data_bits:
        pad_val = 0xEC if pad_toggle == 0 else 0x11
        pad_toggle ^= 1
        for shift in range(7, -1, -1):
            bits.append((pad_val >> shift) & 1)

    data_cw = [
        sum(bits[i + b] << (7 - b) for b in range(8))
        for i in range(0, len(bits), 8)
    ]

    data_blocks: list[list[int]] = []
    ec_blocks: list[list[int]] = []
    offset = 0
    for cnt, dlen in block_groups:
        for _ in range(cnt):
            blk = data_cw[offset : offset + dlen]
            offset += dlen
            data_blocks.append(blk)
            ec_blocks.append(_rs_remainder(blk, ec_per_block))

    interleaved: list[int] = []
    max_dlen = max(len(b) for b in data_blocks)
    for i in range(max_dlen):
        for blk in data_blocks:
            if i < len(blk):
                interleaved.append(blk[i])
    for i in range(ec_per_block):
        for blk in ec_blocks:
            interleaved.append(blk[i])

    all_bits: list[int] = []
    for cw in interleaved:
        for shift in range(7, -1, -1):
            all_bits.append((cw >> shift) & 1)
    all_bits.extend([0] * rem_bits)

    size = 17 + 4 * version
    modules = [[False] * size for _ in range(size)]
    is_func = [[False] * size for _ in range(size)]

    def set_func(r: int, c: int, val: bool) -> None:
        if 0 <= r < size and 0 <= c < size:
            modules[r][c] = val
            is_func[r][c] = True

    for fr, fc in ((0, 0), (0, size - 7), (size - 7, 0)):
        for dr in range(-1, 8):
            for dc in range(-1, 8):
                rr, cc = fr + dr, fc + dc
                if 0 <= rr < size and 0 <= cc < size:
                    dark = (
                        0 <= dr <= 6
                        and 0 <= dc <= 6
                        and (
                            dr in (0, 6)
                            or dc in (0, 6)
                            or (2 <= dr <= 4 and 2 <= dc <= 4)
                        )
                    )
                    set_func(rr, cc, dark)

    for i in range(8, size - 8):
        set_func(6, i, i % 2 == 0)
        set_func(i, 6, i % 2 == 0)
    set_func(size - 8, 8, True)

    for ar in align_pos:
        for ac in align_pos:
            if is_func[ar][ac]:
                continue
            for dr in range(-2, 3):
                for dc in range(-2, 3):
                    dark = max(abs(dr), abs(dc)) != 1
                    set_func(ar + dr, ac + dc, dark)

    for i in range(9):
        if not is_func[8][i]:
            set_func(8, i, False)
        if not is_func[i][8]:
            set_func(i, 8, False)
    for i in range(1, 8):
        set_func(size - i, 8, False)
    for i in range(1, 9):
        set_func(8, size - i, False)

    if version >= 7:
        vrem = version << 12
        for i in range(5, -1, -1):
            if vrem & (1 << (i + 12)):
                vrem ^= 0x1F25 << i
        vbits = (version << 12) | vrem
        for i in range(18):
            bit = bool((vbits >> i) & 1)
            r, c = i // 3, size - 11 + (i % 3)
            set_func(r, c, bit)
            set_func(c, r, bit)

    bit_idx = 0
    col = size - 1
    upward = True
    while col > 0:
        if col == 6:
            col -= 1
        rows = range(size - 1, -1, -1) if upward else range(size)
        for r in rows:
            for dc in (0, -1):
                c = col + dc
                if not is_func[r][c]:
                    bit_val = bool(all_bits[bit_idx]) if bit_idx < len(all_bits) else False
                    modules[r][c] = bit_val ^ ((r + c) % 2 == 0)
                    bit_idx += 1
        col -= 2
        upward = not upward

    fmt_data = 1 << 3
    fmt_rem = fmt_data << 10
    for i in range(4, -1, -1):
        if fmt_rem & (1 << (i + 10)):
            fmt_rem ^= 0x537 << i
    fmt_bits = ((fmt_data << 10) | fmt_rem) ^ 0x5412

    tl_coords = (
        [(8, c) for c in range(6)]
        + [(8, 7), (8, 8), (7, 8)]
        + [(r, 8) for r in range(5, -1, -1)]
    )
    br_coords = [(size - 1 - i, 8) for i in range(7)] + [
        (8, size - 8 + i) for i in range(8)
    ]
    for idx in range(15):
        bit = bool((fmt_bits >> (14 - idx)) & 1)
        r1, c1 = tl_coords[idx]
        modules[r1][c1] = bit
        r2, c2 = br_coords[idx]
        modules[r2][c2] = bit

    return modules


def _png_chunk(tag: bytes, data: bytes) -> bytes:
    return (
        struct.pack('>I', len(data))
        + tag
        + data
        + struct.pack('>I', zlib.crc32(tag + data) & 0xFFFFFFFF)
    )


def _render_qr_fallback(url: str, fmt: str) -> tuple[bytes, str]:
    modules = _encode_qr_matrix(url)
    size = len(modules)
    border = 2
    scale = 5
    dim = size + 2 * border

    if fmt == 'svg':
        px = dim * scale
        paths = [
            f'M{c + border},{r + border}h1v1h-1z'
            for r, row in enumerate(modules)
            for c, val in enumerate(row)
            if val
        ]
        svg = (
            f'<svg xmlns="http://www.w3.org/2000/svg" width="{px}" height="{px}" '
            f'viewBox="0 0 {dim} {dim}" shape-rendering="crispEdges">'
            f'<rect width="100%" height="100%" fill="#ffffff"/>'
            f'<path d="{"".join(paths)}" fill="#000000"/></svg>'
        )
        return svg.encode('utf-8'), 'image/svg+xml'

    img_dim = dim * scale
    rows_raw: list[bytes] = []
    for py in range(img_dim):
        mr = (py // scale) - border
        if 0 <= mr < size:
            src_row = modules[mr]
            row_bytes = bytearray(b'\xff' * img_dim)
            for mc, val in enumerate(src_row):
                if val:
                    start = (mc + border) * scale
                    row_bytes[start : start + scale] = b'\x00' * scale
            rows_raw.append(b'\x00' + bytes(row_bytes))
        else:
            rows_raw.append(b'\x00' + (b'\xff' * img_dim))

    ihdr = struct.pack('>IIBBBBB', img_dim, img_dim, 8, 0, 0, 0, 0)
    idat = zlib.compress(b''.join(rows_raw), level=6)
    png_bytes = (
        b'\x89PNG\r\n\x1a\n'
        + _png_chunk(b'IHDR', ihdr)
        + _png_chunk(b'IDAT', idat)
        + _png_chunk(b'IEND', b'')
    )
    return png_bytes, 'image/png'


@asynccontextmanager
async def lifespan(app: FastAPI):
    init_db()
    yield


app = FastAPI(title='Agent-Generated URL Shortener', version='1.0.0', lifespan=lifespan)


class ShortenRequest(BaseModel):
    url: str
    custom_alias: str | None = None


class ShortenResponse(BaseModel):
    code: str
    short_url: str
    original_url: str


class LinkMetadataResponse(BaseModel):
    code: str
    original_url: str
    short_url: str
    created_at: str
    clicks: int


@app.get('/health')
def health() -> dict:
    return {'status': 'ok'}


@app.post('/shorten', response_model=ShortenResponse, status_code=201)
def shorten_url(payload: ShortenRequest, request: Request) -> ShortenResponse:
    base = str(request.base_url).rstrip('/')
    try:
        result = create_short_link(
            payload.url,
            custom_alias=payload.custom_alias,
            base_url=base,
        )
    except InvalidInputError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    except AliasConflictError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    except RuntimeError as exc:
        raise HTTPException(status_code=503, detail=str(exc)) from exc
    return ShortenResponse(**result)


@app.get('/stats/{code}')
def url_stats(code: str) -> dict:
    stats = fetch_url_stats(code)
    if not stats:
        raise HTTPException(status_code=404, detail='Short URL not found')
    return stats


@app.get('/metadata/{code}', response_model=LinkMetadataResponse)
def link_metadata(code: str, request: Request) -> LinkMetadataResponse:
    base = str(request.base_url).rstrip('/')
    metadata = get_link_metadata(code, base_url=base)
    if not metadata:
        raise HTTPException(status_code=404, detail='Short URL not found')
    return LinkMetadataResponse(**metadata)


@app.get('/qr/{code}')
def link_qr_code(code: str, request: Request, format: str = 'png') -> Response:
    base = str(request.base_url).rstrip('/')
    try:
        qr_result = generate_qr_code(code, base_url=base, image_format=format)
    except InvalidInputError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    except ModuleNotFoundError:
        fmt = format.lower().strip()
        if fmt not in {'png', 'svg'}:
            raise HTTPException(
                status_code=400,
                detail="Unsupported QR code format. Use 'png' or 'svg'.",
            )
        metadata = get_link_metadata(code, base_url=base)
        if not metadata:
            raise HTTPException(status_code=404, detail='Short URL not found')
        qr_bytes, media_type = _render_qr_fallback(metadata['short_url'], fmt)
        return Response(content=qr_bytes, media_type=media_type)
    if not qr_result:
        raise HTTPException(status_code=404, detail='Short URL not found')
    qr_bytes, media_type = qr_result
    return Response(content=qr_bytes, media_type=media_type)


@app.get('/{code}')
def redirect_url(code: str) -> RedirectResponse:
    original_url = resolve_short_url(code)
    if not original_url:
        raise HTTPException(status_code=404, detail='Short URL not found')
    return RedirectResponse(url=original_url, status_code=307)
